input.command:
cd "$ARCHON_HORIZON_ROOT" && "$HORIZON_BIN" usage --json 2>/dev/null | python3 -c "
import json,sys
d=json.load(sys.stdin)
for k in ('paused','recent_failure_reasons'): print(k,':',d.get(k))
s=d.get('session') or {}
print('session tokens_in',s.get('tokens_in'),'out',s.get('tokens_out'),'cost',s.get('cost_usd'))
r=d.get('run') or {}
print('run cost',r.get('cost_usd'),'budget',d.get('budget'))
"
